head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.fileRowcount;
scwin.real_invstg_impr_seq;
scwin.gClickId;
scwin.vScrenID = "ULDSTF37076.xml";
scwin.onpageload = function() {

};
scwin.onpageunload = function() {
};
scwin.fn_GetCode = function() {
    dts_KnowlgTp.DataID = "/CodeAction.do?method=listCodeValueName&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=C&CD_ENG_NM=DELIB_STEP_TP_CD";
    dts_KnowlgTp.Reset();
};
scwin.fn_single_read = function() {
    trs_Read.Action = "/RealInvstgImpr.do?method=readRealInvstgImpr&REAL_INVSTG_IMPR_SEQ=" + scwin.real_invstg_impr_seq + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyName = "toinb_dataid4";
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_registerRealInvstgImpr,O:pOutput3=dts_fileList)";
    trs_Read.Post();
};
scwin.fn_save = function() {
    if (txb_isur_cd.getValue() == "" || txb_isur_cd.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "법인코드(명)"));
        txb_isur_cd.focus();
        return;
    }
    var delib = $c.cp.valueOfIndex(delib_step_tp_cd, "VALUE", delib_step_tp_cd.getSelectedIndex());
    if (delib.length < 1) {
        $c.win.alert("[심의단계]를 선택하세요.");
        delib_step_tp_cd.focus();
        return;
    }
    if (comite_dd.getValue() == "") {
        $c.win.alert("[위원회 일자]를 입력하세요.");
        comite_dd.focus();
        return;
    }
    if (file_name.getValue() == "" || file_name.getValue().indexOf(" ") == "") {
        $c.win.alert("[첨부파일]은 반드시 첨부하셔야합니다.");
        file_name.focus();
        return;
    }
    var rtn = confirm('위사항을 입력 하시겠습니까?');
    if (rtn == 1) // [확인] 버튼이 눌려졌을 경우

    {
        reg_emp_no.setValue(js_id);
        trs_Save.Action = "/RealInvstgImpr.do?method=registerRealInvstgImpr" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pDetail=dts_registerRealInvstgImpr,I:pFile=dts_fileList)";
        trs_Save.Post();
    }
};
scwin.fn_SetInfoHeader = function() {
    dts_registerRealInvstgImpr.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DSCLMGT_INSERT_INVSTGIMRP_INOUT";
    dts_registerRealInvstgImpr.Reset();
    dts_registerRealInvstgImpr.insertRow();
};



//파일 다운로드
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?REAL_INVSTG_IMPR_SEQ=" + scwin.real_invstg_impr_seq + "&ATTACH_SEQ=" + attach_seq + "&gubun=63";
};
scwin.checkMaxLength = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkFileSize = function() {
    var maxFileSize = 1024 * 1024 * 50; //50MB		
    var mySize = inf_find.fileInfo("size");
    if (mySize < maxFileSize) {
        return true;
    } else {
        return false;
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearch_IR(txb_isur_cd, txb_com_abbrv);
};
scwin.trs_Read_OnSuccess = function() {

};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.trs_Save_OnSuccess = async function() {
    var msg = trs_Save.ErrorMsg;
    if (msg == "T") {
        $c.win.alert($c.stf.getMessageParam("MSG-A001", "개선계획의 주요내용 입력 "));
        $c.frame.path("../").fn_list_sync();
        await $c.frame.CloseFrame();
    } else {
        $c.win.alert($c.stf.getMessageParam("MSG-A002", "개선계획의 주요내용 입력 "));
    }
};
scwin.trs_Save_OnFail = function() {
    var msg = $c.stf.getMessageParam("MSG-A002", "개선계획의 주요내용 입력 ");
};
scwin.save_onclick = function() {
    scwin.fn_save();
};
scwin.cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.inf_find_OnClick = function() {
    var filenm = file_name.getValue();
    dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
    file_name.setValue(inf_find.getValue());
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
if (scwin.real_invstg_impr_seq != "input") {
    scwin.fileRowcount = dts_fileList.getTotalRow();
}
scwin.fileRowcount++;
if (scwin.fileRowcount >= 2) {
    $c.win.alert("더이상 추가하실수 없습니다.");
    scwin.fileRowcount = 1;
} else {
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        var fileName = inf_find.getValue();
        if (filename.indexOf('\') > 0) {,fileName=filename.substring(filename.lastIndexOf('\
                ')+1);,txb_filenmsize.setValue(fileName), ( !$c.stf.checkMaxLength(txb_filenmsize,80,"파일명") ) ,{dts_fileList : dts_fileList , txb_filenmsize : txb_filenmsize , return : return}, ( !scwin.checkFileSize() ) ,{alert : function([object Object]){  	

                $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
                return;
            }
        }, dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue()), file_name.setValue(inf_find.getValue()))), {
    dts_fileList: dts_fileList,
    txb_filenmsize: txb_filenmsize
}))
function btn_linedelete_onclick() {
    if (scwin.fileRowcount > 0) scwin.fileRowcount--;
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};

function grd_fileList_OnDblClick(row, colid) {
    if (row == 0) return;
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
    }
};

function Grd_com_isur_OnKeyPress(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

function Grd_com_isur_OnDblClick(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

function Grd_com_isur_OnClick(row, colid) {
    Grd_com_isur.style.display = "";
};

function Grd_com_isur_OnSetFocus() {
    stFocusGrid = true;
};

function Grd_com_isur_OnKillFocus() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

function txb_isur_cd_onblur() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};

function txb_isur_cd_onfocus() {
    Grd_com_isur.style.display = "none";
};

function txb_isur_cd_onkeyup() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};

function MxDataSet_com_isur_OnFilter(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else {
        return true;
    }
};

function icn_SCal_onclick() {
    popUpCalendar2(comite_dd);
};

function gform_onload() {
    scwin.fn_GetCode();
    $c.cm.PanelToGroupBox(panel_Top);
    scwin.real_invstg_impr_seq = $c.frame.path("../").scwin.real_invstg_impr_seq;
    $c.stf.showObj(file_name, false);
    $c.stf.showObj(belng_dep_cd, false);
    $c.stf.showObj(ld_mkt_tp_cd, false);
    $c.stf.showObj(txb_filenmsize, false);
    scwin.gClickId = $c.frame.path("../").clickId;

    //조회화면 onload
    if (scwin.gClickId != "input") {
        $c.stf.showObj(pnl_1, true);
        $c.stf.showObj(pnl_2, false);
        $c.stf.showObj(save, false);
        txb_isur_cd.setDisabled("true");
        img_com_srch.style.display = "none";
        scwin.fn_single_read();
    } else {
        //등록화면 onload
        scwin.fn_SetInfoHeader();
        //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 


        //fn_setFileDataHeader();
        scwin.fileRowcount = 0;
        reg_ddtm.setValue($c.ut.cGetToday("yyyymmdd"));
        reg_emp_no.setValue(js_emp_nm);
        belng_dep_cd.setValue(js_dep_cd);
        ld_mkt_tp_cd.setValue(js_market);
        $c.stf.showObj(pnl_1, false);
    }
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
};
}
}
};
